import{_ as t,c as a,o,ag as r}from"./chunks/framework.DuVOYUUM.js";const p=JSON.parse('{"title":"Nvidia Jetson","description":"","frontmatter":{"order":4},"headers":[],"relativePath":"projects/igvc-2024/software/jetson.md","filePath":"projects/igvc-2024/software/jetson.md","lastUpdated":1790647345000}'),i={name:"projects/igvc-2024/software/jetson.md"};function l(n,e,s,h,d,c){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="nvidia-jetson" tabindex="-1">Nvidia Jetson <a class="header-anchor" href="#nvidia-jetson" aria-label="Permalink to &quot;Nvidia Jetson&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#overview">Overview</a></li><li><a href="#specs">Specs</a></li><li><a href="#jetpacks">Jetpacks</a><ul><li><a href="#flashing-a-jetpack">Flashing a JetPack</a></li></ul></li><li><a href="#installing-software">Installing Software</a></li><li><a href="#can">CAN</a></li></ul></nav><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Nvidia Jetson is a small computer developed for use with smart robotics. Specifically, the module used on Horizon is the Jetson Orin Nano 8GB. The module can simultaneously run compute-intensive tasks, like image processing, neural networks, or planning algorithms without high electrical demand. An introduction, including documentation, a setup guide, and hardware specs can be found at <a href="https://developer.nvidia.com/embedded/learn/jetson-orin-nano-devkit-user-guide/index.html#introduction" target="_blank" rel="noreferrer">Jetson Orin Nano Developer Kit User Guide</a>.</p><h2 id="specs" tabindex="-1">Specs <a class="header-anchor" href="#specs" aria-label="Permalink to &quot;Specs&quot;">​</a></h2><ul><li><strong>CPU</strong>: 6-core Arm® Cortex®-A78AE @ 1.5 GHz</li><li><strong>GPU</strong>: 1024-core NVIDIA Ampere architecture GPU @ 625 MHz</li><li><strong>RAM</strong>: 8GB LPDDR5</li><li><strong>Storage</strong>: MicroSD Card or NVMe via M.2 <ul><li>We currently have a 128 GB MicroSD</li></ul></li><li><strong>I/O</strong><ul><li>4x USB 3.2 Gen2</li><li>1x USB Type-C (for flashing firmware)</li><li>1x Gigabit Ethernet</li><li>1x DisplayPort</li></ul></li><li>More details <ul><li><a href="https://www.nvidia.com/en-us/autonomous-machines/embedded-systems/jetson-orin/" target="_blank" rel="noreferrer">https://www.nvidia.com/en-us/autonomous-machines/embedded-systems/jetson-orin/</a></li><li><a href="https://developer.nvidia.com/embedded/learn/jetson-orin-nano-devkit-user-guide/hardware_spec.html" target="_blank" rel="noreferrer">https://developer.nvidia.com/embedded/learn/jetson-orin-nano-devkit-user-guide/hardware_spec.html</a></li></ul></li></ul><h2 id="jetpacks" tabindex="-1">Jetpacks <a class="header-anchor" href="#jetpacks" aria-label="Permalink to &quot;Jetpacks&quot;">​</a></h2><p>The software running on the Jetson is Nvidia&#39;s proprietary &quot;<a href="https://developer.nvidia.com/embedded/jetpack" target="_blank" rel="noreferrer">JetPacks</a>,&quot; which are special versions of Ubuntu that are paired with a special bootloader and Linux kernel.</p><h3 id="flashing-a-jetpack" tabindex="-1">Flashing a JetPack <a class="header-anchor" href="#flashing-a-jetpack" aria-label="Permalink to &quot;Flashing a JetPack&quot;">​</a></h3><h4 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h4><ul><li>A laptop or VM running the version of Ubuntu you wish to flash to the Jetson <ul><li>E.g. If you wish to flash Ubuntu 20.04 to the Jetson, the laptop or VM must have Ubuntu 20.04 installed as well</li></ul></li><li>A high-speed USB Type-C to Type-A cable <ul><li>For some reason, I&#39;ve only been able to get the cable that comes with the ZED to work with it. Other cables may work, haven&#39;t really tried any 🤷</li></ul></li><li>A female-to-female jumper cable <ul><li>Used for shorting the pins that put the Jetson into recovery mode</li></ul></li><li>The Jetson, with the MicroSD Card plugged into it</li><li>An Nvidia Developer account <ul><li>Create an account <a href="https://developer.nvidia.com/" target="_blank" rel="noreferrer">here</a> by pressing &quot;Join&quot; at the top-right of the page.</li></ul></li></ul><h4 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h4><ol><li>On the &quot;host&quot; laptop, <a href="https://docs.nvidia.com/sdk-manager/download-run-sdkm/index.html" target="_blank" rel="noreferrer">download and install the Nvidia SDK Manager</a>. <ul><li>You can do either the direct download or network repository method</li></ul></li><li>Connect the Jetson to the computer with the Type-C-to-Type-A cable.</li><li>With the jumper cable, short the pins labeled &quot;FC_REC&quot; and &quot;GND.&quot;</li><li>Power up the Jetson.</li><li><a href="https://docs.nvidia.com/sdk-manager/install-with-sdkm-jetson/index.html" target="_blank" rel="noreferrer">Install the Jetpack</a>. <ul><li>Generally, you can accept the defaults. </li><li>For the username and password, use <code>ora</code> and <code>ora-2023</code>, respectively</li><li>It is not necessary to install the &quot;Additional SDKs&quot; (DeepStream, Rivermax, etc.)</li></ul></li><li>Once the installation has been completed, you can proceed to use the Jetson as normal.</li></ol><h2 id="installing-software" tabindex="-1">Installing Software <a class="header-anchor" href="#installing-software" aria-label="Permalink to &quot;Installing Software&quot;">​</a></h2><p>Most software should be able to be installed on the Jetson, similar to any other Ubuntu system. One thing to make note of is the Jetson&#39;s different CPU architecture. The Jetson is <code>arm64</code>-based rather than the usual <code>x86</code> you might find on most computers. If you are trying to install something on the Jetson, and the software is acting weird or not installing at all, check that you are installing/have installed the correct build of that piece of software. For our purposes, <a href="https://www.ros.org/reps/rep-2000.html#humble-hawksbill-may-2022-may-2027" target="_blank" rel="noreferrer">ROS 2 supports <code>arm64</code></a>, and the ZED SDK has <a href="https://www.stereolabs.com/developers/release#nvidia-jetson-504616ef8d38" target="_blank" rel="noreferrer">special builds specifically for Jetson</a>.</p><h2 id="can" tabindex="-1">CAN <a class="header-anchor" href="#can" aria-label="Permalink to &quot;CAN&quot;">​</a></h2><p>See <a href="https://docs.nvidia.com/jetson/archives/r36.2/DeveloperGuide/HR/ControllerAreaNetworkCan.html" target="_blank" rel="noreferrer">this.</a></p>',17)]))}const m=t(i,[["render",l]]);export{p as __pageData,m as default};
